import {renderMapApi} from './mobile-map-api.mjs';

// Renders the host↔renderer protocol for the embedded runtime, Swift and Kotlin from one contract,
// packages/mobile-runtime/protocol.json. scripts/mobile-protocol-generate.mjs writes or checks the
// outputs; this module stays free of file access so its rules can be tested directly.

export const banner =
  '// Generated by scripts/mobile-protocol-generate.mjs. Edit protocol.json, then regenerate.\n';

const identifier = /^[a-z][A-Za-z0-9]*$/u;
const integer = (value, minimum) => Number.isSafeInteger(value) && value >= minimum;

/** Every rule the hosts and the runtime rely on. Returns the problems found, or none. */
export function validateProtocol(contract) {
  const problems = [];
  const fail = (message) => problems.push(message);
  if (!integer(contract.version, 1)) fail('version must be a positive integer.');
  if (!integer(contract.minimumVersion, 1) || contract.minimumVersion > contract.version)
    fail('minimumVersion must be a positive integer no greater than version.');
  const limits = contract.limits ?? {};
  for (const name of [
    'maximumMessageBytes',
    'maximumPendingRequests',
    'requestTimeoutMs',
    'maximumDataBytes',
    'maximumDataTotalBytes',
    'maximumDataReferences',
    'maximumThrottleMs',
    'warningWindowMs',
  ]) {
    if (!integer(limits[name], 1)) fail(`limits.${name} must be a positive integer.`);
  }
  if (limits.maximumDataBytes > limits.maximumDataTotalBytes)
    fail('limits.maximumDataBytes cannot exceed limits.maximumDataTotalBytes.');
  if (limits.maximumMessageBytes >= limits.maximumDataBytes)
    fail('limits.maximumDataBytes must exceed limits.maximumMessageBytes.');
  const names = (label, values) => {
    if (!Array.isArray(values) || values.length === 0) fail(`${label} must be a non-empty list.`);
    else {
      if (new Set(values).size !== values.length) fail(`${label} has duplicates.`);
      for (const value of values) if (!identifier.test(value)) fail(`${label}: ${value}`);
    }
    return Array.isArray(values) ? values : [];
  };
  const described = (label, value) => {
    const keys = names(label, Object.keys(value ?? {}));
    for (const key of keys)
      if (typeof value[key] !== 'string' || !value[key].endsWith('.'))
        fail(`${label}.${key} needs a sentence of description.`);
    return keys;
  };
  const methods = names('methods', contract.methods);
  for (const required of ['initialize', 'cancel', 'setEvents', 'dispose'])
    if (!methods.includes(required)) fail(`methods must include ${required}.`);
  const levels = described('eventLevels', contract.eventLevels);
  const events = names('events', Object.keys(contract.events ?? {}));
  for (const name of events) {
    const event = contract.events[name];
    const keys = Object.keys(event).sort().join(',');
    if (keys === 'delivery') {
      if (event.delivery !== 'always') fail(`events.${name}.delivery must be "always".`);
    } else if (keys !== 'level' || !levels.includes(event.level)) {
      fail(`events.${name} needs one level from eventLevels, or delivery "always".`);
    }
  }
  for (const required of ['hello', 'error'])
    if (contract.events?.[required]?.delivery !== 'always')
      fail(`events.${required} must be delivered without a subscription.`);
  for (const level of levels)
    if (!events.some((name) => contract.events[name].level === level))
      fail(`eventLevels.${level} has no events.`);
  described('cameraReasons', contract.cameraReasons);
  described('resourceKinds', contract.resourceKinds);
  described('errorReasons', contract.errorReasons);
  const errors = names('errors', Object.keys(contract.errors ?? {}));
  for (const code of errors) {
    const error = contract.errors[code];
    if (typeof error.recoverable !== 'boolean')
      fail(`errors.${code}.recoverable must be a boolean.`);
    if (
      !Array.isArray(error.sources) ||
      error.sources.length === 0 ||
      error.sources.some((source) => !['host', 'runtime'].includes(source))
    )
      fail(`errors.${code}.sources must name host, runtime or both.`);
    if (typeof error.description !== 'string' || !error.description.endsWith('.'))
      fail(`errors.${code} needs a sentence of description.`);
    for (const [platform, text] of Object.entries(error.documentation ?? {}))
      if (
        !['swift', 'kotlin'].includes(platform) ||
        typeof text !== 'string' ||
        !text.endsWith('.')
      )
        fail(`errors.${code}.documentation.${platform} must be a sentence for swift or kotlin.`);
  }
  for (const required of ['invalidRequest', 'incompatibleRuntime', 'cancelled', 'disposed'])
    if (!contract.errors?.[required]?.sources?.includes('runtime'))
      fail(`errors.${required} must be available to the runtime.`);
  return problems;
}

/** The runtime uses the names and classifications from the native API. */
export function runtimeContract(contract) {
  const names = (value) => Object.keys(value);
  return {
    ...contract,
    eventLevels: names(contract.eventLevels),
    cameraReasons: names(contract.cameraReasons),
    resourceKinds: names(contract.resourceKinds),
    errorReasons: names(contract.errorReasons),
    errors: Object.fromEntries(
      Object.entries(contract.errors).map(([code, {recoverable, sources}]) => [
        code,
        {recoverable, sources},
      ]),
    ),
  };
}

/**
 * Generated files by repository path. `typescript` formats the runtime contract with the
 * repository's Prettier configuration.
 */
export async function renderProtocol(contract, {typescript}) {
  const problems = validateProtocol(contract);
  if (problems.length) throw new Error(`Invalid protocol.json:\n${problems.join('\n')}`);
  return {
    'packages/mobile-runtime/src/contract.ts': await typescript(
      `${banner}export const protocol = ${JSON.stringify(runtimeContract(contract), null, 2)} as const;\n`,
    ),
    ...renderMapApi(contract, banner),
  };
}
